-- Frozen schema of Step 0A; synthetic migration fixture, no citizen data.
CREATE TABLE incidents (
	id CHAR(32) NOT NULL, 
	incident_type VARCHAR(17) NOT NULL, 
	payment_method VARCHAR(13) NOT NULL, 
	amount NUMERIC(12, 2), 
	incident_time DATETIME, 
	occurred_at DATETIME, 
	transaction_id VARCHAR(128), 
	transaction_status VARCHAR(32), 
	is_fraud_ongoing BOOLEAN, 
	is_account_compromised BOOLEAN, 
	is_credentials_exposed BOOLEAN, 
	is_otp_shared BOOLEAN, 
	is_pin_shared BOOLEAN, 
	is_password_shared BOOLEAN, 
	is_remote_access_granted BOOLEAN, 
	unauthorized_activity_continuing BOOLEAN, 
	potential_additional_loss BOOLEAN, 
	account_secured BOOLEAN, 
	evidence_available BOOLEAN, 
	incident_subtype VARCHAR(128), 
	affected_person_type VARCHAR(64), 
	platform VARCHAR(64), 
	account_type VARCHAR(64), 
	immediate_danger BOOLEAN, 
	threat_or_blackmail BOOLEAN, 
	content_still_online BOOLEAN, 
	account_access VARCHAR(32), 
	attacker_active BOOLEAN, 
	sensitive_information_exposed BOOLEAN, 
	evidence_types JSON, 
	urgency_score INTEGER, 
	other_crime_sub_category VARCHAR(19), 
	details JSON, 
	urgency VARCHAR(10) NOT NULL, 
	urgency_computed_at DATETIME, 
	severity VARCHAR(10), 
	ongoing_risk VARCHAR(10), 
	recovery_window VARCHAR(32), 
	urgency_reasons JSON, 
	status VARCHAR(15) NOT NULL, 
	created_at DATETIME DEFAULT (CURRENT_TIMESTAMP) NOT NULL, 
	updated_at DATETIME DEFAULT (CURRENT_TIMESTAMP) NOT NULL, 
	PRIMARY KEY (id)
);
CREATE TABLE evidence (
	id CHAR(32) NOT NULL, 
	incident_id CHAR(32) NOT NULL, 
	original_filename VARCHAR(255) NOT NULL, 
	stored_filename VARCHAR(255) NOT NULL, 
	content_type VARCHAR(128), 
	size_bytes INTEGER NOT NULL, 
	created_at DATETIME DEFAULT (CURRENT_TIMESTAMP) NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(incident_id) REFERENCES incidents (id) ON DELETE CASCADE, 
	UNIQUE (stored_filename)
);
CREATE INDEX ix_evidence_incident_id ON evidence (incident_id);
